<?php
namespace App\Http\Controllers; use App\Enums\ReservationStatus; use App\Models\{Folio,Guest,Reservation,ReservationRoom,Room,RoomType}; use App\Services\Reservations\AvailabilityService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class ReservationWebController extends Controller { public function index(Request $r){$pid=$r->user()->property_id;$q=Reservation::with(['guest','rooms.room','folio'])->where('property_id',$pid);if($r->filled('status'))$q->where('status',$r->status);if($r->filled('search'))$q->where(function($x)use($r){$x->where('reference','like','%'.$r->search.'%')->orWhereHas('guest',fn($g)=>$g->where('first_name','like','%'.$r->search.'%')->orWhere('last_name','like','%'.$r->search.'%')->orWhere('phone','like','%'.$r->search.'%'));});$reservations=$q->latest('check_in_at')->paginate(20)->withQueryString();return view('reservations.index',compact('reservations'));} public function create(Request $r){$pid=$r->user()->property_id;$types=RoomType::where('property_id',$pid)->where('is_active',true)->get();$rooms=Room::with('roomType')->where('property_id',$pid)->where('is_active',true)->orderBy('room_number')->get();return view('reservations.create',compact('types','rooms'));} public function store(Request $r,AvailabilityService $availability){$pid=$r->user()->property_id;$d=$r->validate(['first_name'=>'required|max:120','last_name'=>'nullable|max:120','phone'=>'nullable|max:50','email'=>'nullable|email|max:190','nationality'=>'nullable|max:100','id_type'=>'nullable|max:50','id_number'=>'nullable|max:120','room_id'=>'required|exists:rooms,id','check_in_at'=>'required|date','check_out_at'=>'required|date|after:check_in_at','adults'=>'required|integer|min:1|max:20','children'=>'nullable|integer|min:0|max:20','nightly_rate'=>'required|numeric|min:0','deposit_required'=>'nullable|numeric|min:0','source'=>'required|max:50','special_requests'=>'nullable|max:2000']);$room=Room::where('property_id',$pid)->findOrFail($d['room_id']);return DB::transaction(function()use($d,$room,$pid,$r,$availability){abort_unless($availability->lockRoomIfAvailable($room,$d['check_in_at'],$d['check_out_at']),422,'The selected room is not available for those dates.');$guest=null;if(!empty($d['phone']))$guest=Guest::where('property_id',$pid)->where('phone',$d['phone'])->first();if(!$guest && !empty($d['email']))$guest=Guest::where('property_id',$pid)->where('email',$d['email'])->first();if(!$guest)$guest=Guest::create(['property_id'=>$pid,'first_name'=>$d['first_name'],'last_name'=>$d['last_name']??null,'phone'=>$d['phone']??null,'email'=>$d['email']??null,'nationality'=>$d['nationality']??null,'id_type'=>$d['id_type']??null,'id_number'=>$d['id_number']??null]);else $guest->update(array_filter(['first_name'=>$d['first_name'],'last_name'=>$d['last_name']??null,'email'=>$d['email']??null,'phone'=>$d['phone']??null,'nationality'=>$d['nationality']??null,'id_type'=>$d['id_type']??null,'id_number'=>$d['id_number']??null],fn($v)=>$v!==null&&$v!==''));$n=max(1,\Carbon\Carbon::parse($d['check_in_at'])->startOfDay()->diffInDays(\Carbon\Carbon::parse($d['check_out_at'])->startOfDay()));$sub=$n*$d['nightly_rate'];$res=Reservation::create(['property_id'=>$pid,'guest_id'=>$guest->id,'reference'=>config('hms.reservation_prefix','RES').'-'.now()->format('Ymd').'-'.strtoupper(Str::random(6)),'status'=>ReservationStatus::Confirmed,'source'=>$d['source'],'check_in_at'=>$d['check_in_at'],'check_out_at'=>$d['check_out_at'],'adults'=>$d['adults'],'children'=>$d['children']??0,'subtotal'=>$sub,'grand_total'=>$sub,'deposit_required'=>$d['deposit_required']??0,'special_requests'=>$d['special_requests']??null,'created_by'=>$r->user()->id]);ReservationRoom::create(['reservation_id'=>$res->id,'room_id'=>$room->id,'room_type_id'=>$room->room_type_id,'nightly_rate'=>$d['nightly_rate'],'adults'=>$d['adults'],'children'=>$d['children']??0,'check_in_at'=>$d['check_in_at'],'check_out_at'=>$d['check_out_at']]);return redirect()->route('reservations.show',$res)->with('success','Reservation created successfully.');});} public function show(Request $r,Reservation $reservation){abort_unless($reservation->property_id===$r->user()->property_id,404);$reservation->load(['guest','rooms.room.roomType','folio.items','folio.payments','stays.room']);return view('reservations.show',compact('reservation'));} public function calendar(Request $r){$pid=$r->user()->property_id;$from=now()->startOfDay();$days=collect(range(0,13))->map(fn($i)=>$from->copy()->addDays($i));$rooms=Room::with(['roomType','reservationRooms'=>fn($q)=>$q->where('check_out_at','>',$from)->where('check_in_at','<',$from->copy()->addDays(14))->with('reservation.guest')])->where('property_id',$pid)->orderBy('room_number')->get();return view('reservations.calendar',compact('days','rooms'));} }
